<script setup lang="ts">
import {devControlsEnabled} from "../../../config/presentation";
import type {ValveAsset} from '../../../types/pipeline';defineProps<{valves:ValveAsset[];selected:string;busy:boolean;nearest:{upstream:string[];downstream:string[]}}>();const emit=defineEmits<{'select':[id:string];'control':[id:string,status:'open'|'closed']}>();const dev=devControlsEnabled;
</script><template><section class="panel valve-panel"><h3>阀门与检修边界</h3><p>最近上游：<button v-for="id in nearest.upstream" :key="id" @click="emit('select',id)">{{id}}</button><span v-if="!nearest.upstream.length">无</span></p><p>最近下游：<button v-for="id in nearest.downstream" :key="id" @click="emit('select',id)">{{id}}</button><span v-if="!nearest.downstream.length">无</span></p><div class="valve-list"><div v-for="v in valves" :key="v.id" :class="{selected:selected===v.id}"><button @click="emit('select',v.id)">{{v.id}} <small>{{v.status==='open'?'开启':v.status==='closed'?'关闭':'故障'}}</small></button><select v-if="dev" :aria-label="`${v.id} 阀门状态`" :value="v.status" :disabled="busy||v.status==='fault'" @change="emit('control',v.id,($event.target as HTMLSelectElement).value as 'open'|'closed')"><option value="open">Open</option><option value="closed">Closed</option></select></div></div><small v-if="dev">开发控制 · 状态会保存，用于连通性验证</small></section></template>
